/* DWARF original prototype: void SetSkillLevel(CHARACTER * this, DWORD dwVnum, BYTE bLev) */

void __thiscall CHARACTER::SetSkillLevel(CHARACTER *this,DWORD dwVnum,BYTE bLev)

{
  TPlayerSkill *pTVar1;
  int iVar2;
  
  pTVar1 = this->m_pSkillLevels;
  if (pTVar1 != (TPlayerSkill *)0x0) {
    iVar2 = MIN(0x28,(uint)bLev);
    pTVar1[dwVnum].bLevel = (BYTE)iVar2;
    if (bLev < 0x28) {
      if (bLev < 0x1e) {
        if (0x13 < bLev) {
          this->m_pSkillLevels[dwVnum].bMasterType = '\x01';
        }
      }
      else {
        this->m_pSkillLevels[dwVnum].bMasterType = '\x02';
      }
    }
    else {
      this->m_pSkillLevels[dwVnum].bMasterType = '\x03';
    }
  }
  return;
}
